我們的 LINE 群組任務 bot 下週要上線（Bun + Hono + bun:sqlite），這是 webhook 的主程式。可以幫我做上線前的 code review 嗎？請找出會出事的地方，依嚴重度排序，每點附修正方式。

```ts
// src/webhook.ts
import { Hono } from "hono";
import { createHmac, timingSafeEqual } from "node:crypto";
import { db } from "./db";
import { classify } from "./llm";       // 呼叫 LLM，通常 3~15 秒
import { taskCard } from "./flex";

const app = new Hono();
const SECRET = process.env.LINE_CHANNEL_SECRET!;
const TOKEN = process.env.LINE_CHANNEL_ACCESS_TOKEN!;

function verify(raw: string, sig: string) {
  const mac = createHmac("sha256", SECRET).update(raw).digest();
  return timingSafeEqual(mac, Buffer.from(sig, "base64"));
}

function reply(replyToken: string, messages: unknown[]) {
  return fetch("https://api.line.me/v2/bot/message/reply", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${TOKEN}` },
    body: JSON.stringify({ replyToken, messages }),
  });
}

app.post("/webhook", async (c) => {
  const raw = await c.req.text();
  if (!verify(raw, c.req.header("x-line-signature") ?? "")) return c.text("bad signature", 403);
  const { events } = JSON.parse(raw);

  for (const ev of events) {
    // 避免同一則訊息處理兩次
    db.run("INSERT OR REPLACE INTO messages (id, group_id, user_id, text) VALUES (?, ?, ?, ?)",
      [ev.message?.id, ev.source.groupId, ev.source.userId, ev.message?.text]);

    if (ev.type === "message" && ev.message.type === "text") {
      // 有人 @ bot 才處理
      if (!ev.message.text.includes("@任務小幫手")) continue;

      // 發言者名字
      const prof = await fetch(`https://api.line.me/v2/bot/profile/${ev.source.userId}`, {
        headers: { Authorization: `Bearer ${TOKEN}` },
      }).then((r) => r.json());

      const assignees = (ev.message.mention?.mentions ?? []).map((m: any) => m.userId);
      const task = await classify(ev.message.text);   // 回傳 { title }
      const id = db.run(
        "INSERT INTO tasks (group_id, title, assignees, created_by) VALUES (?, ?, ?, ?)",
        [ev.source.groupId, task.title, JSON.stringify(assignees), prof.displayName],
      ).lastInsertRowid;

      await reply(ev.replyToken, [
        {
          type: "textV2",
          text: `{owner} 已建立任務：${task.title}`,
          substitution: { owner: { type: "mention", mentionee: { type: "user", userId: ev.source.userId } } },
        },
        { type: "flex", altText: "任務卡", contents: taskCard(id, task.title) }, // 按鈕 postback data: `done=${id}`
      ]);
    }

    if (ev.type === "postback") {
      const id = new URLSearchParams(ev.postback.data).get("done");
      db.run("UPDATE tasks SET status = 'done' WHERE id = ?", [id]);
      await reply(ev.replyToken, [{ type: "text", text: `任務 ${id} 已完成 ✅` }]);
    }

    if (ev.type === "message" && ev.message.type === "file") {
      const res = await fetch(`https://api-data.line.me/v2/bot/message/${ev.message.id}/content`, {
        headers: { Authorization: `Bearer ${TOKEN}` },
      });
      await Bun.write(`./uploads/${ev.message.fileName}`, await res.arrayBuffer());
    }
  }
  return c.text("ok");
});

export default app;
```
